use genewars_runtime::{creature_world::*,actor_activation::TrigTables,physics_tables::PhysicsTables};
use std::{fs,path::PathBuf};
fn main(){let p=PathBuf::from(std::env::args().nth(1).unwrap());let tables=PathBuf::from(std::env::args().nth(2).unwrap());let physics=PhysicsTables::from_mapped_bytes(&fs::read(tables.join("angles.bin")).unwrap(),&fs::read(tables.join("bounce.bin")).unwrap()).unwrap();let trig=TrigTables::generate_pinned().unwrap();let animations=MuleAnimations::from_anb(&fs::read(tables.join("mule.anb")).unwrap()).unwrap();let map=fs::read(p.join("map.bin")).unwrap();let input=fs::read(p.join("input.bin")).unwrap();let mut actual=Vec::new();
for row in input.chunks_exact(128){let frame=u32::from_le_bytes(row[..4].try_into().unwrap());let before:[u8;124]=row[4..].try_into().unwrap();let prefix=plan_common_straight_motion_prefix(&before,frame,&physics,&trig,true,true,true).unwrap();let target=[i16::from_le_bytes(prefix[11..13].try_into().unwrap()),i16::from_le_bytes(prefix[13..15].try_into().unwrap())];let(got,effect)=plan_mule_after_admitted_prefix_with_water_policy(&before,&prefix,target,&map,MuleStepContext{frame_counter:frame,gravity:1024,water_height:2000,climate:148},&physics,&trig,|_,_,_|Ok(0),|_|Ok(false),&animations,|_|panic!("timer20 must not rechoose"),true).unwrap();assert!(effect.is_none());actual.extend_from_slice(&got.after);}
fs::write(p.join("actual.bin"),actual).unwrap();}
